package com.jnapanam.sportszone.release1.service;
import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AdvancedLifecycleService{
 private final JdbcTemplate jdbc;public AdvancedLifecycleService(JdbcTemplate j){jdbc=j;}
 @Transactional public Map<String,Object> membership(UUID actor,UUID id,String action,String details){String a=action.toUpperCase();if(a.equals("FREEZE"))jdbc.update("update customer_memberships set frozen_until=current_date+interval '30 day' where id=?",id);if(a.equals("RESUME"))jdbc.update("update customer_memberships set frozen_until=null where id=?",id);if(a.equals("EXTEND"))jdbc.update("update customer_memberships set end_date=end_date+30 where id=?",id);UUID e=UUID.randomUUID();jdbc.update("insert into membership_lifecycle_events(id,membership_id,action,details,actor_user_id) values(?,?,?,?,?)",e,id,a,details,actor);return one("select * from membership_lifecycle_events where id=?",e);}
 @Transactional public Map<String,Object> entitlement(UUID actor,UUID id,String entitlement,int qty,String ref){UUID e=UUID.randomUUID();jdbc.update("insert into membership_entitlement_ledger(id,membership_id,entitlement,quantity,reference) values(?,?,?,?,?)",e,id,entitlement,qty,ref);return one("select * from membership_entitlement_ledger where id=?",e);}
 public List<Map<String,Object>> membershipHistory(UUID id){return jdbc.queryForList("select * from membership_lifecycle_events where membership_id=? order by created_at desc",id);}
 @Transactional public Map<String,Object> training(UUID actor,UUID enrollment,String action,String details){UUID e=UUID.randomUUID();jdbc.update("insert into training_lifecycle_events(id,enrollment_id,action,details,actor_user_id) values(?,?,?,?,?)",e,enrollment,action.toUpperCase(),details,actor);return one("select * from training_lifecycle_events where id=?",e);}
 @Transactional public Map<String,Object> waitlist(UUID user,UUID batch,String participant){Integer pos=jdbc.queryForObject("select coalesce(max(position),0)+1 from training_waitlist where batch_id=?",Integer.class,batch);UUID id=UUID.randomUUID();jdbc.update("insert into training_waitlist(id,batch_id,user_id,participant_name,position) values(?,?,?,?,?)",id,batch,user,participant,pos);return one("select * from training_waitlist where id=?",id);}
 @Transactional public Map<String,Object> progress(UUID coach,UUID enrollment,String note){UUID id=UUID.randomUUID();jdbc.update("insert into training_progress_notes(id,enrollment_id,coach_user_id,note) values(?,?,?,?)",id,enrollment,coach,note);return one("select * from training_progress_notes where id=?",id);}
 @Transactional public Map<String,Object> certificate(UUID enrollment){UUID id=UUID.randomUUID();String no="JNZ-CERT-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();jdbc.update("insert into training_certificates(id,enrollment_id,certificate_number) values(?,?,?) on conflict(enrollment_id) do nothing",id,enrollment,no);return one("select * from training_certificates where enrollment_id=?",enrollment);}
 @Transactional public Map<String,Object> official(UUID tournament,String name,String role){UUID id=UUID.randomUUID();jdbc.update("insert into tournament_officials(id,tournament_id,official_name,role) values(?,?,?,?)",id,tournament,name,role);return one("select * from tournament_officials where id=?",id);}
 @Transactional public Map<String,Object> result(UUID actor,UUID tournament,UUID fixture,String result,String reason){UUID id=UUID.randomUUID();jdbc.update("insert into tournament_result_history(id,tournament_id,fixture_id,new_result,reason,submitted_by) values(?,?,?,?,?,?)",id,tournament,fixture,result,reason,actor);return one("select * from tournament_result_history where id=?",id);}
 @Transactional public Map<String,Object> approveResult(UUID actor,UUID id){jdbc.update("update tournament_result_history set status='APPROVED',approved_by=?,approved_at=now() where id=?",actor,id);return one("select * from tournament_result_history where id=?",id);}
 @Transactional public Map<String,Object> closeTournament(UUID actor,UUID tournament,long income,long expense,String notes){UUID id=UUID.randomUUID();jdbc.update("insert into tournament_financial_closure(id,tournament_id,income_paise,expense_paise,notes,closed_by) values(?,?,?,?,?,?) on conflict(tournament_id) do update set income_paise=excluded.income_paise,expense_paise=excluded.expense_paise,notes=excluded.notes,closed_by=excluded.closed_by,closed_at=now()",id,tournament,income,expense,notes,actor);return one("select * from tournament_financial_closure where tournament_id=?",tournament);}
 @Transactional public Map<String,Object> dataRequest(UUID user,String type,String notes){UUID id=UUID.randomUUID();jdbc.update("insert into account_data_requests(id,user_id,request_type,notes) values(?,?,?,?)",id,user,type.toUpperCase(),notes);return one("select * from account_data_requests where id=?",id);}
 @Transactional public Map<String,Object> mergeRequest(UUID actor,UUID source,UUID target,boolean verified){UUID id=UUID.randomUUID();jdbc.update("insert into account_merge_requests(id,source_user_id,target_user_id,verified_mobile,requested_by) values(?,?,?,?,?)",id,source,target,verified,actor);return one("select * from account_merge_requests where id=?",id);}
 @Transactional public Map<String,Object> schedule(UUID user,String category,String type,UUID ref,Instant at){UUID id=UUID.randomUUID();jdbc.update("insert into reminder_schedule(id,user_id,category,reference_type,reference_id,scheduled_at) values(?,?,?,?,?,?)",id,user,category,type,ref,at);return one("select * from reminder_schedule where id=?",id);}
 public List<Map<String,Object>> reports(){return jdbc.queryForList("select 'OPEN_SUPPORT' metric,count(*) value from support_tickets where status not in ('RESOLVED','CLOSED') union all select 'OPEN_INCIDENTS',count(*) from operations_incidents where status<>'RESOLVED' union all select 'PENDING_REFUNDS',count(*) from payment_refunds where status not in ('COMPLETED','REJECTED') union all select 'PENDING_REMINDERS',count(*) from reminder_schedule where status='PENDING'");}
 private Map<String,Object> one(String q,Object...a){return jdbc.queryForMap(q,a);}
}
